MIB = 1024 * 1024

MARK_RE = re.compile(r"⟦(.+?)⟧", re.S)
FACTS: dict[str, list[tuple[str, str]]] = defaultdict(list)
GROUND_TEXT: dict[str, str] = {}  # rel -> «истинный» текст для нечитаемых файлов (скан, png, truncated)
NOTES: dict[str, dict] = {}  # служебные сведения для манифеста (смещения, размеры)


def clean(text: str, rel: str | None, where: str) -> str:
    """Вырезает ⟦⟧ и регистрирует факты для файла rel."""
    if rel is not None:
        for m in MARK_RE.finditer(text):
            FACTS[rel].append((m.group(1), where))
    return MARK_RE.sub(lambda m: m.group(1), text)


def strip(text: str) -> str:
    return MARK_RE.sub(lambda m: m.group(1), text)


# ---------------------------------------------------------------- рендеры
def build_docx(blocks, rel, path, header=None, footer=None,
               author="Отдел документационного обеспечения СТК",
               created=datetime(2026, 1, 15, 10, 0)):
    d = Document()
    st = d.styles["Normal"]
    st.font.name = "Times New Roman"
    st.font.size = Pt(12)
    rfonts = st.element.get_or_add_rPr().get_or_add_rFonts()
    for k in ("w:cs", "w:eastAsia", "w:ascii", "w:hAnsi"):
        rfonts.set(qn(k), "Times New Roman")
    title = None
    for blk in blocks:
        kind = blk[0]
        if kind == "title":
            title = strip(blk[1])
            d.add_heading(clean(blk[1], rel, "body"), level=0)
        elif kind in ("h1", "h2"):
            d.add_heading(clean(blk[1], rel, "body"), level=1 if kind == "h1" else 2)
        elif kind == "p":
            d.add_paragraph(clean(blk[1], rel, "body"))
        elif kind == "ol":
            for it in blk[1]:
                d.add_paragraph(clean(it, rel, "body"), style="List Number")
        elif kind == "ul":
            for it in blk[1]:
                d.add_paragraph(clean(it, rel, "body"), style="List Bullet")
        elif kind == "table":
            rows = blk[1]
            t = d.add_table(rows=len(rows), cols=len(rows[0]))
            t.style = "Table Grid"
            for i, row in enumerate(rows):
                for j, val in enumerate(row):
                    cell = t.cell(i, j)
                    cell.text = clean(val, rel, "table")
                    if i == 0:
                        for r in cell.paragraphs[0].runs:
                            r.bold = True
            d.add_paragraph("")
        elif kind == "code":
            p = d.add_paragraph()
            run = p.add_run(clean(blk[1], rel, "body"))
            run.font.name = "Courier New"
        else:
            raise ValueError(kind)
    sec = d.sections[0]
    if header:
        sec.header.is_linked_to_previous = False
        sec.header.paragraphs[0].text = clean(header, rel, "header")
    if footer:
        sec.footer.is_linked_to_previous = False
        sec.footer.paragraphs[0].text = clean(footer, rel, "footer")
    cp = d.core_properties
    cp.author = author
    cp.last_modified_by = author
    cp.created = created
    cp.modified = created
    cp.revision = 1
    if title:
        cp.title = title
    d.save(path)


def blocks_to_text(blocks, rel, flavor="txt"):
    out: list[str] = []
    n_ol = 0
    for blk in blocks:
        kind = blk[0]
        if kind == "title":
            t = clean(blk[1], rel, "body")
            if flavor == "txt":
                out += [t.upper(), "=" * min(len(t), 78), ""]
            else:
                out += [f"# {t}", ""]
        elif kind == "h1":
            t = clean(blk[1], rel, "body")
            out += ([t, "-" * min(len(t), 78), ""] if flavor == "txt" else [f"## {t}", ""])
        elif kind == "h2":
            t = clean(blk[1], rel, "body")
            out += ([t, ""] if flavor == "txt" else [f"### {t}", ""])
        elif kind == "p":
            out += [clean(blk[1], rel, "body"), ""]
        elif kind == "ol":
            for i, it in enumerate(blk[1], 1):
                out.append(f"{i}{')' if flavor == 'txt' else '.'} {clean(it, rel, 'body')}")
            out.append("")
            n_ol += 1
        elif kind == "ul":
            for it in blk[1]:
                out.append(f"{'—' if flavor == 'txt' else '-'} {clean(it, rel, 'body')}")
            out.append("")
        elif kind == "table":
            rows = [[clean(c, rel, "table") for c in r] for r in blk[1]]
            if flavor == "md":
                out.append("| " + " | ".join(rows[0]) + " |")
                out.append("|" + "---|" * len(rows[0]))
                for r in rows[1:]:
                    out.append("| " + " | ".join(r) + " |")
            else:
                for r in rows:
                    out.append(" | ".join(r))
            out.append("")
        elif kind == "code":
            body = clean(blk[1], rel, "body")
            if flavor == "md":
                out += ["```text", body, "```", ""]
            else:
                out += [textwrap.indent(body, "    "), ""]
        else:
            raise ValueError(kind)
    return "\n".join(out).rstrip() + "\n"


def soffice(fmt: str, inputs, outdir: Path):
    outdir.mkdir(parents=True, exist_ok=True)
    cmd = ["soffice", f"-env:UserInstallation=file://{LO_PROFILE}", "--headless", "--norestore",
           "--convert-to", fmt, "--outdir", str(outdir)] + [str(p) for p in inputs]
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=900)
    ext = fmt.split(":")[0]
    for p in inputs:
        target = outdir / (Path(p).stem + "." + ext)
        if not target.exists():
            raise RuntimeError(f"soffice не создал {target}\n{r.stdout}\n{r.stderr}")


