def build_pptx(slides, rel, path, register=True):
    prs = Presentation()
    r = rel if register else None
    for s in slides:
        if s["layout"] == "title":
            sl = prs.slides.add_slide(prs.slide_layouts[0])
            sl.shapes.title.text = clean(s["title"], r, "slide")
            sl.placeholders[1].text = clean(s["subtitle"], r, "slide")
        elif s["layout"] == "bullets":
            sl = prs.slides.add_slide(prs.slide_layouts[1])
            sl.shapes.title.text = clean(s["title"], r, "slide")
            tf = sl.placeholders[1].text_frame
            for i, b in enumerate(s["bullets"]):
                p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
                p.text = clean(b, r, "slide")
                p.font.size = PPt(20)
        elif s["layout"] == "table":
            sl = prs.slides.add_slide(prs.slide_layouts[5])
            sl.shapes.title.text = clean(s["title"], r, "slide")
            rows = s["table"]
            shp = sl.shapes.add_table(len(rows), len(rows[0]), Inches(0.4), Inches(1.7), Inches(9.2), Inches(3.5))
            for i, row in enumerate(rows):
                for j, val in enumerate(row):
                    cell = shp.table.cell(i, j)
                    cell.text = clean(val, r, "table")
                    cell.text_frame.paragraphs[0].font.size = PPt(16)
        if s.get("notes"):
            sl.notes_slide.notes_text_frame.text = clean(s["notes"], r, "notes")
    prs.core_properties.author = "Отдел персонала СТК"
    prs.core_properties.title = strip(slides[0]["title"])
    prs.save(path)


