def cap(s):
    return s[0].upper() + s[1:]


def purpose(rng: random.Random) -> str:
    p = rng.choice(PURPOSES)
    return (", " if p.startswith("чтобы") else " ") + p


def sentence(rng: random.Random, objs):
    o = rng.choice(objs)
    c = rng.choice
    k = rng.randrange(14)
    if k == 0:
        return f"{c(CONDS)}, {c(ROLES)} {c(VERBS)} {o}."
    if k == 1:
        return f"Порядок {o} применяется {c(SCOPES)}."
    if k == 2:
        return f"{cap(c(ROLES))} {c(VERBS)} {o}{purpose(rng)}."
    if k == 3:
        return f"Сведения о ходе {o} {c(RESULTS)}."
    if k == 4:
        return f"Допускается {c(PERMS)} при условии {c(COND_GEN)}."
    if k == 5:
        return f"Не допускается {c(FORBID)}."
    if k == 6:
        return f"При возникновении разногласий в ходе {o} вопрос выносится на рассмотрение {c(AUTHS)}."
    if k == 7:
        return f"{cap(c(ROLES))} вправе запросить {c(DOCS_ACC)}{purpose(rng)}."
    if k == 8:
        return f"Результаты {o} оформляются {c(FORMS)} и хранятся {c(STORAGE)}."
    if k == 9:
        return f"Сроки {o} устанавливаются {c(DEADLINES)}."
    if k == 10:
        return f"В случае {c(INCIDENTS)} {c(ROLES)} незамедлительно информирует {c(WHOM)}."
    if k == 11:
        return f"Изменения в порядок {o} вносятся {c(CHANGES)}."
    if k == 12:
        return f"Участники {o} руководствуются настоящим разделом, локальными нормативными актами и {c(EXTRA)}."
    return f"{cap(c(ROLES))} {c(VERBS)} {o}, а при необходимости привлекает {c(HELPERS)}."


def regulation_sections(rng: random.Random):
    """Бесконечный поток разделов: (номер раздела, заголовок, список абзацев)."""
    n = 0
    while True:
        order = list(range(len(TOPICS)))
        rng.shuffle(order)
        for ti in order:
            n += 1
            title, objs = TOPICS[ti]
            head = f"Раздел {n}. {title}{rng.choice(SUFFIXES)}"
            paras = []
            for k in range(1, rng.randint(6, 11) + 1):
                sents = " ".join(sentence(rng, objs) for _ in range(rng.randint(2, 4)))
                paras.append(f"{n}.{k}. {sents}")
            yield n, head, paras


def build_needle(rel, path: Path, rng: random.Random, target=285_000):
    needle = ("Резервные копии архива подписанных договоров хранятся во внешнем депозитарии "
              "⟦«Кварц-Хранение»⟧ под шифром ⟦АРХ-7741-Щ⟧; доступ к копиям предоставляется только по "
              "письменному запросу генерального директора.")
    parts = ["СВОД ОПЕРАЦИОННЫХ РЕГЛАМЕНТОВ ООО «СЕВЕРНАЯ ТЕСТОВАЯ КОМПАНИЯ»",
             "Сводная редакция для внутреннего пользования. Документ объединяет действующие операционные "
             "регламенты подразделений; при расхождении с отдельным положением применяется более поздний документ.",
             ""]
    length = sum(len(p) + 1 for p in parts)
    inserted = False
    for n, head, paras in regulation_sections(rng):
        parts += [head, ""]
        length += len(head) + 2
        for k, p in enumerate(paras, 1):
            parts.append(p)
            length += len(p) + 1
            if not inserted and length >= target // 2:
                np = f"{n}.{k}.1. " + clean(needle, rel, "body")
                parts.append(np)
                length += len(np) + 1
                inserted = True
        parts.append("")
        length += 1
        if length >= target:
            break
    text = "\n".join(parts) + "\n"
    path.write_text(text, encoding="utf-8")
    off = text.index("АРХ-7741-Щ")
    NOTES["needle"] = {"chars": len(text), "offset": off, "ratio": off / len(text),
                       "offset_depo": text.index("«Кварц-Хранение»")}


def filler_text(rng: random.Random, min_chars: int, start_section=1):
    parts, length = [], 0
    for n, head, paras in regulation_sections(rng):
        block = head + "\n\n" + "\n".join(paras) + "\n\n"
        parts.append(block)
        length += len(block)
        if length >= min_chars:
            break
    return "".join(parts)


def write_exact_bytes(path: Path, text: str, target: int):
    b = text.encode("utf-8")
    if len(b) > target:
        b = b[:target].decode("utf-8", errors="ignore").encode("utf-8")
    b = b + b"\n" * (target - len(b))
    assert len(b) == target
    path.write_bytes(b)


def render_png(lines, path: Path, size=(1100, 520)):
    img = Image.new("RGB", size, "white")
    d = ImageDraw.Draw(img)
    fb, fr = ImageFont.truetype(FONT_B, 34), ImageFont.truetype(FONT, 26)
    y = 40
    for i, ln in enumerate(lines):
        d.text((50, y), ln, font=fb if i == 0 else fr, fill=(20, 20, 20))
        y += 60 if i == 0 else 42
    d.rectangle([20, 20, size[0] - 20, size[1] - 20], outline=(180, 0, 0), width=4)
    img.save(path, "PNG")


