def num(*vals):
    """Варианты записи числа: «4 750», «4750» (NBSP/узкий пробел нормализуются при проверке)."""
    out = []
    for v in vals:
        out.append(v)
        if " " in v:
            out.append(v.replace(" ", ""))
    return out


def T(q, expect, forbid=None, computed=False):
    t = {"q": q, "expect": expect}
    if forbid:
        t["forbid"] = forbid
    return (t, computed)


def add(cat, turns, sources, origin="documents", note=None):
    if not isinstance(turns, list):
        turns = [turns]
    n = sum(1 for c in GOLDEN if c["category"] == cat) + 1
    cid = f"{PREFIX[cat]}-{n:03d}"
    case = {"id": cid, "category": cat, "turns": [t for t, _ in turns], "sources": sources, "expect_origin": origin}
    if note:
        case["note"] = note
    for i, (_, comp) in enumerate(turns):
        if comp:
            COMPUTED.add((cid, i))
    GOLDEN.append(case)


